    public Optional<Room> find(int number) {
        return rooms.stream().filter(r -> r.number() == number).findFirst();
    }

    public Room get(int number) {
        return find(number).orElseThrow(() -> new IllegalStateException("Quarto desconhecido: " + number));
    }

    public int size() {
        return rooms.size();
    }
}
